#!/bin/bash
# Prints the three most frequent IP addresses in access.log, one per line,
# most frequent first; ties broken by first appearance in the log.
awk '
NF > 0 && $1 ~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/ {
    ip = $1
    count[ip]++
    if (!(ip in first)) first[ip] = ++n
}
END {
    for (i = 0; i < 3; i++) {
        best = ""
        for (ip in count) {
            if (!(ip in used)) {
                if (best == "" ||
                    count[ip] > count[best] ||
                    (count[ip] == count[best] && first[ip] < first[best]))
                    best = ip
            }
        }
        if (best == "") break
        used[best] = 1
        print best
    }
}
' access.log
